// Custom Worker entry: OpenNext handles HTTP; we add the Queue consumer, a scheduled
// handler (bounded embedding backfill) and the ReadingRoom Durable Object.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import openNext from "./.open-next/worker.js";
import { handleQueue } from "./src/lib/cf/consumer.js";
import { runEmbedBackfill } from "./src/lib/cf/backfill.js";

export { ReadingRoom } from "./src/lib/cf/reading-room.js";

export default {
  fetch: (request, env, ctx) => openNext.fetch(request, env, ctx),
  queue: (batch, env) => handleQueue(batch, env),
  // Every 30 minutes: embed the next small batch of books for semantic search.
  scheduled: (event, env, ctx) => {
    if (env.EMBED_BACKFILL === "0") return;
    ctx.waitUntil(runEmbedBackfill(env, { batch: Number(env.EMBED_BATCH) || 40 }));
  },
};
